/* FatihHoca | UltraMat — Öğrenci Takip · Ödev Takip Formu (sürüm 0.12)
 * Yalnızca "Ödev Takip Formu" ekranı açılınca yüklenir (uygulamanın açılışını ağırlaştırmasın diye):
 * Nunito yazı tipi, logo ve A5 form şablonu. Biçim karne-uret'teki Veli Bilgi Formu ile aynıdır.
 * Öğrencinin adı ve şubesi basılı gelir; ödev satırlarını öğrenci kendisi doldurur.
 * 1–20: ders kitabının ön kapağının içine · 21–40: arka kapağının içine (köşelerinden bantlanır). */
"use strict";
(function () {
  const LOGO = '<img src="data:image/png;base64," width="54" height="54" style="display:block;">';

  const CSS = `@font-face{font-family:'OdNunito';font-weight:800;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:'OdNunito';font-weight:800;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0100-02AF,U+0304,U+0308,U+0329,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'OdNunito';font-weight:900;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:'OdNunito';font-weight:900;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');unicode-range:U+0100-02AF,U+0304,U+0308,U+0329,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'OdNunito';font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
/* Ödev Takip Formu — A5 dikey (148 × 210 mm). Veli Bilgi Formu (karne-uret) ile aynı biçim. */
.otSayfa{width:148mm;height:210mm;box-sizing:border-box;padding:9mm 10mm 8mm;font-family:"OdNunito",sans-serif;color:#111827;position:relative;background:#fff;overflow:hidden;
  -webkit-print-color-adjust:exact;print-color-adjust:exact;}
.otSayfa *{font-family:"OdNunito",sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.otBant{position:absolute;width:15mm;height:15mm;background:linear-gradient(135deg,#E5E7EB 50%,transparent 50%);}
.otBant.sol{left:0;top:0;}
.otBant.sa{right:0;top:0;transform:scaleX(-1);}
.otBant.asol{left:0;bottom:0;transform:scaleY(-1);}
.otBant.asa{right:0;bottom:0;transform:scale(-1,-1);}
.otUst{display:flex;justify-content:space-between;align-items:center;border-bottom:2.2px solid #7C3AED;padding-bottom:1.8mm;}
.otMarka{font-weight:900;font-size:13pt;color:#3B0764;line-height:1.1;display:flex;align-items:center;gap:2.4mm;}
.otMarka span span{color:#F97316;}
.otMarka small{display:block;font-size:7pt;font-weight:800;letter-spacing:1.6px;color:#64748B;line-height:1.3;}
.otLogo img{width:34px;height:auto;display:block;}
.otBaslik{font-weight:900;font-size:13pt;color:#3B0764;}
.otBilgi{display:flex;align-items:stretch;margin:3.5mm 0 4mm;}
.otAlan{padding:0 4mm;border-left:.6pt solid #D1D5DB;display:flex;flex-direction:column;justify-content:flex-end;}
.otAlan:first-child{padding-left:0;border-left:none;}
.otAlan.genis{flex:1;min-width:0;}
.otEtiket{font-size:6.5pt;font-weight:800;color:#6B7280;letter-spacing:.15mm;}
.otDeger{font-size:10.5pt;font-weight:900;color:#111827;margin-top:.5mm;line-height:1.1;}
.otDeger.uzun{font-size:9pt;} .otDeger.cokUzun{font-size:7.5pt;}
.otTablo{width:100%;border-collapse:collapse;table-layout:fixed;}
.otTablo th{font-size:7.5pt;font-weight:800;color:#374151;text-align:left;padding:0 1.5mm 1.5mm;border-bottom:.9pt solid #111827;vertical-align:bottom;line-height:1.2;}
.otTablo th.no,.otTablo th.ort{text-align:center;}
.otTablo th+th{border-left:.5pt solid #9CA3AF;}
.otTablo td{height:6.6mm;padding:0 1.5mm;border-bottom:.5pt solid #9CA3AF;font-size:8.5pt;vertical-align:middle;}
.otTablo td+td{border-left:.5pt solid #9CA3AF;}
.otTablo tr:nth-child(even) td{background:#F7F7F8;}
.otTablo td.no{font-weight:900;text-align:center;color:#111827;}
.otTablo td.kutu{text-align:center;}
.otTablo td.kutu span{display:inline-block;box-sizing:content-box;width:3.4mm;height:3.4mm;border:.9pt solid #111827;border-radius:.8mm;background:#fff;vertical-align:middle;}
.otSoz{margin:5.2mm 6mm 0;text-align:center;font-size:8pt;font-weight:800;color:#3B0764;line-height:1.45;}
.otAlt{position:absolute;left:10mm;right:10mm;bottom:8mm;display:flex;justify-content:space-between;align-items:center;gap:6mm;border-top:.6pt solid #9CA3AF;padding-top:2.2mm;}
.otNot{flex:1;font-size:6.5pt;font-weight:600;color:#374151;line-height:1.4;}
.otYer{font-weight:800;color:#3B0764;}
.otImza{text-align:center;line-height:1.2;}
.otImza b{display:block;font-size:9.5pt;font-weight:900;color:#111827;}
.otImza small{display:block;font-size:7pt;font-weight:800;color:#374151;margin-top:.4mm;}`;

  const SATIR = 20;
  /** Sayfanın başlangıcına göre (0 → 1–20, 20 → 21–40) kapak ve söz. */
  const SAYFA = {
    0: { kapak: "ön", soz: "Ödevi bitirmek görev, ödevi anlamak kazançtır." },
    20: { kapak: "arka", soz: "Bir gün çalışmak heves, her gün çalışmak karakterdir." }
  };
  const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

  /** Tek öğrencinin A5 sayfası. o = { sinif, ad, bas } (bas: 0 ya da 20). */
  function sayfaHtml(o) {
    const bas = SAYFA[o.bas] ? o.bas : 0, s = SAYFA[bas];
    const ad = String(o.ad || "").trim();
    const adSinif = ad.length > 34 ? " cokUzun" : ad.length > 26 ? " uzun" : "";
    let satirlar = "";
    for (let i = 1; i <= SATIR; i++) satirlar += '<tr><td class="no">' + (bas + i) + '</td><td></td><td></td><td class="kutu"><span></span></td></tr>';
    return '<div class="otSayfa"><div class="otBant sol"></div><div class="otBant sa"></div><div class="otBant asol"></div><div class="otBant asa"></div>' +
      '<div class="otUst"><div class="otMarka"><span class="otLogo">' + LOGO + '</span><span>FatihHoca | <span>UltraMat</span><small>MATEMATİK GELİŞİM ANALİZİ</small></span></div><div class="otBaslik">Ödev Takip Formu</div></div>' +
      '<div class="otBilgi"><div class="otAlan"><span class="otEtiket">Sınıf / Şube</span><span class="otDeger">' + esc(o.sinif) + '</span></div>' +
      '<div class="otAlan genis"><span class="otEtiket">Öğrenci Adı Soyadı</span><span class="otDeger' + adSinif + '">' + esc(ad) + '</span></div>' +
      '<div class="otAlan"><span class="otEtiket">Ders</span><span class="otDeger">Matematik</span></div></div>' +
      '<table class="otTablo"><colgroup><col style="width:10mm"><col><col style="width:36mm"><col style="width:16mm"></colgroup>' +
      '<thead><tr><th class="no">Sıra</th><th>Ödev</th><th class="ort">Ödev Kontrol Tarihi</th><th class="ort">Kontrol</th></tr></thead><tbody>' + satirlar + '</tbody></table>' +
      '<div class="otSoz">' + s.soz + '</div>' +
      '<div class="otAlt"><span class="otNot"><span class="otYer">Matematik ders kitabının ' + s.kapak + ' kapağının içine yapıştır.</span><br>' +
      'Ödevini ve tarihini yaz, kontrol gününden önce bitir, kontrol edilince kutuyu işaretle.</span>' +
      '<span class="otImza"><b>Fatih KARYAĞDI</b><small>Matematik Öğretmeni</small></span></div></div>';
  }

  window.ODEV_FORMU = { SURUM: "0.12", SATIR, CSS, sayfaHtml };
})();
